    "upstream.v165.message131": "Modelo de separación de capas",
    "upstream.v165.message132": "Seleccionar modelo de separación",
    "upstream.v165.message133": "{p0}\nSeparación automática: elige las capas necesarias según la estructura real de la imagen, sin fijar sujetos ni número de capas; conserva la imagen base completa y evita fragmentarla en exceso.",
    "upstream.v165.message134": "{p0}\n\nDa prioridad a las regiones seleccionadas por el usuario. Coordenadas de selección (sistema de coordenadas de imagen 0-1000): {p1}",
    "upstream.v165.message135": "Región {p0} <bbox>{p1}</bbox>",
    "upstream.v165.message136": "Iniciar separación",
    "upstream.v165.message137": "Cine y vídeo",
